def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'C'

    last_me, last_opp = history[-1]

    c_opp = 0
    d_opp = 0
    my_d = 0
    last_my_D = -1

    for i in range(n):
        a, b = history[i]
        if a == 'D':
            my_d += 1
            last_my_D = i
        if b == 'C':
            c_opp += 1
        else:
            d_opp += 1

    if d_opp == n:
        return 'D'

    start = n - 10
    if start < 0:
        start = 0

    recent_c = 0
    recent_d = 0
    for i in range(start, n):
        if history[i][1] == 'C':
            recent_c += 1
        else:
            recent_d += 1

    streak_d = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        streak_d += 1
        i -= 1

    streak_c = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'C':
        streak_c += 1
        i -= 1

    hard = False
    if recent_d >= 8 or streak_d >= 5:
        hard = True
    if recent_d >= 6 and d_opp >= c_opp:
        hard = True
    if n >= 25 and d_opp * 10 >= n * 7:
        hard = True

    if hard:
        return 'D'

    rem = 100 - n
    if rem <= 1:
        return 'D'

    dc = 0
    dd = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D' and history[i - 1][1] == 'C':
            if history[i][1] == 'C':
                dc += 1
            else:
                dd += 1

    coop_rate = c_opp / n
    recent_len = n - start
    recent_good = recent_c >= 8 and coop_rate >= 0.75

    push_aggr = dc >= 2 and dd == 0 and recent_good
    push_periodic = dc >= 1 and dd == 0 and recent_good

    since_my_D = n - last_my_D - 1 if last_my_D >= 0 else n

    if last_opp == 'D':
        if last_me == 'D':
            return 'C'
        if n >= 2 and history[-2][0] == 'D':
            return 'C'
        return 'D'

    if last_me == 'D':
        if push_aggr:
            return 'D'
        return 'C'

    if push_aggr:
        return 'D'

    if my_d == 0 and n >= 20 and d_opp == 0 and recent_d == 0 and rem > 6:
        return 'D'

    if push_periodic and since_my_D >= 4 and streak_c >= 3 and rem > 6:
        return 'D'

    return 'C'
